mkitem!{mkstruct!{# [doc = " This inner struct exists to keep it all behind a single lock;"] # [doc = " this is done to prevent possible deadlocks in a multi-threaded compiler,"] # [doc = " as well as inconsistent state observation."] struct DiagCtxtInner { flags : DiagCtxtFlags , registry : Registry , # [doc = " The error guarantees from all emitted errors. The length gives the error count."] err_guars : Vec < ErrorGuaranteed > , # [doc = " The error guarantee from all emitted lint errors. The length gives the"] # [doc = " lint error count."] lint_err_guars : Vec < ErrorGuaranteed > , # [doc = " The delayed bugs and their error guarantees."] delayed_bugs : Vec < (DelayedDiagInner , ErrorGuaranteed) > , # [doc = " The error count shown to the user at the end."] deduplicated_err_count : usize , # [doc = " The warning count shown to the user at the end."] deduplicated_warn_count : usize , emitter : Box < DynEmitter > , # [doc = " Must we produce a diagnostic to justify the use of the expensive"] # [doc = " `trimmed_def_paths` function? Backtrace is the location of the call."] must_produce_diag : Option < Backtrace > , # [doc = " Has this diagnostic context printed any diagnostics? (I.e. has"] # [doc = " `self.emitter.emit_diagnostic()` been called?"] has_printed : bool , # [doc = " This flag indicates that an expected diagnostic was emitted and suppressed."] # [doc = " This is used for the `must_produce_diag` check."] suppressed_expected_diag : bool , # [doc = " This set contains the code of all emitted diagnostics to avoid"] # [doc = " emitting the same diagnostic with extended help (`--teach`) twice, which"] # [doc = " would be unnecessary repetition."] taught_diagnostics : FxHashSet < ErrCode > , # [doc = " Used to suggest rustc --explain `<error code>`"] emitted_diagnostic_codes : FxIndexSet < ErrCode > , # [doc = " This set contains a hash of every diagnostic that has been emitted by"] # [doc = " this `DiagCtxt`. These hashes is used to avoid emitting the same error"] # [doc = " twice."] emitted_diagnostics : FxHashSet < Hash128 > , # [doc = " Stashed diagnostics emitted in one stage of the compiler that may be"] # [doc = " stolen and emitted/cancelled by other stages (e.g. to improve them and"] # [doc = " add more information). All stashed diagnostics must be emitted with"] # [doc = " `emit_stashed_diagnostics` by the time the `DiagCtxtInner` is dropped,"] # [doc = " otherwise an assertion failure will occur."] stashed_diagnostics : FxIndexMap < StashKey , FxIndexMap < Span , (DiagInner , Option < ErrorGuaranteed >) > > , future_breakage_diagnostics : Vec < DiagInner > , # [doc = " expected diagnostic will have the level `Expect` which additionally"] # [doc = " carries the [`LintExpectationId`] of the expectation that can be"] # [doc = " marked as fulfilled. This is a collection of all [`LintExpectationId`]s"] # [doc = " that have been marked as fulfilled this way."] # [doc = ""] # [doc = " Emitting expectations after having stolen this field can happen. In particular, an"] # [doc = " `#[expect(warnings)]` can easily make the `UNFULFILLED_LINT_EXPECTATIONS` lint expect"] # [doc = " itself. To avoid needless complexity in this corner case, we tolerate failing to track"] # [doc = " those expectations."] # [doc = ""] # [doc = " [RFC-2383]: https://rust-lang.github.io/rfcs/2383-lint-reasons.html"] fulfilled_expectations : FxIndexSet < LintExpectationId > , # [doc = " The file where the ICE information is stored. This allows delayed_span_bug backtraces to be"] # [doc = " stored along side the main panic backtrace."] ice_file : Option < PathBuf > , }}}
