mkitem!{mkimpl!{impl StableOrd for ItemLocalId { const CAN_USE_UNSTABLE_SORT : bool = true ; const THIS_IMPLEMENTATION_HAS_BEEN_TRIPLE_CHECKED : () = () ; }}}
mkitem!{# [doc = " The `HirId` corresponding to `CRATE_NODE_ID` and `CRATE_DEF_ID`."] pub const CRATE_HIR_ID : HirId = HirId { owner : OwnerId { def_id : CRATE_DEF_ID } , local_id : ItemLocalId :: ZERO } ;}
mkitem!{pub const CRATE_OWNER_ID : OwnerId = OwnerId { def_id : CRATE_DEF_ID } ;}
