mkitem!{mkimpl!{impl ReprOptions { # [inline] pub fn simd (& self) -> bool { self . flags . contains (ReprFlags :: IS_SIMD) } # [inline] pub fn c (& self) -> bool { self . flags . contains (ReprFlags :: IS_C) } # [inline] pub fn packed (& self) -> bool { self . pack . is_some () } # [inline] pub fn transparent (& self) -> bool { self . flags . contains (ReprFlags :: IS_TRANSPARENT) } # [inline] pub fn linear (& self) -> bool { self . flags . contains (ReprFlags :: IS_LINEAR) } # [doc = " Returns the discriminant type, given these `repr` options."] # [doc = " This must only be called on enums!"] pub fn discr_type (& self) -> IntegerType { self . int . unwrap_or (IntegerType :: Pointer (true)) } # [doc = " Returns `true` if this `#[repr()]` should inhabit \"smart enum"] # [doc = " layout\" optimizations, such as representing `Foo<&T>` as a"] # [doc = " single pointer."] pub fn inhibit_enum_layout_opt (& self) -> bool { self . c () || self . int . is_some () } pub fn inhibit_newtype_abi_optimization (& self) -> bool { self . flags . intersects (ReprFlags :: ABI_UNOPTIMIZABLE) } # [doc = " Returns `true` if this `#[repr()]` guarantees a fixed field order,"] # [doc = " e.g. `repr(C)` or `repr(<int>)`."] pub fn inhibit_struct_field_reordering (& self) -> bool { self . flags . intersects (ReprFlags :: FIELD_ORDER_UNOPTIMIZABLE) || self . int . is_some () } # [doc = " Returns `true` if this type is valid for reordering and `-Z randomize-layout`"] # [doc = " was enabled for its declaration crate."] pub fn can_randomize_type_layout (& self) -> bool { ! self . inhibit_struct_field_reordering () && self . flags . contains (ReprFlags :: RANDOMIZE_LAYOUT) } # [doc = " Returns `true` if this `#[repr()]` should inhibit union ABI optimisations."] pub fn inhibits_union_abi_opt (& self) -> bool { self . c () } }}}
mkitem!{# [doc = " The maximum supported number of lanes in a SIMD vector."] # [doc = ""] # [doc = " This value is selected based on backend support:"] # [doc = " * LLVM does not appear to have a vector width limit."] # [doc = " * Cranelift stores the base-2 log of the lane count in a 4 bit integer."] pub const MAX_SIMD_LANES : u64 = 1 << 0xF ;}
mkitem!{mkstruct!{# [doc = " How pointers are represented in a given address space"] # [derive (Copy , Clone , Debug , PartialEq , Eq)] pub struct PointerSpec { # [doc = " The size of the bitwise representation of the pointer."] pointer_size : Size , # [doc = " The alignment of pointers for this address space"] pointer_align : AbiAlign , # [doc = " The size of the value a pointer can be offset by in this address space."] pointer_offset : Size , # [doc = " Pointers into this address space contain extra metadata"] # [doc = " FIXME(workingjubilee): Consider adequately reflecting this in the compiler?"] _is_fat : bool , }}}
mkitem!{mkstruct!{# [doc = " Parsed [Data layout](https://llvm.org/docs/LangRef.html#data-layout)"] # [doc = " for a target, which contains everything needed to compute layouts."] # [derive (Debug , PartialEq , Eq)] pub struct TargetDataLayout { pub endian : Endian , pub i1_align : AbiAlign , pub i8_align : AbiAlign , pub i16_align : AbiAlign , pub i32_align : AbiAlign , pub i64_align : AbiAlign , pub i128_align : AbiAlign , pub f16_align : AbiAlign , pub f32_align : AbiAlign , pub f64_align : AbiAlign , pub f128_align : AbiAlign , pub aggregate_align : AbiAlign , # [doc = " Alignments for vector types."] pub vector_align : Vec < (Size , AbiAlign) > , pub default_address_space : AddressSpace , pub default_address_space_pointer_spec : PointerSpec , # [doc = " Address space information of all known address spaces."] # [doc = ""] # [doc = " # Note"] # [doc = ""] # [doc = " This vector does not contain the [`PointerSpec`] relative to the default address space,"] # [doc = " which instead lives in [`Self::default_address_space_pointer_spec`]."] address_space_info : Vec < (AddressSpace , PointerSpec) > , pub instruction_address_space : AddressSpace , # [doc = " Minimum size of #[repr(C)] enums (default c_int::BITS, usually 32)"] # [doc = " Note: This isn't in LLVM's data layout string, it is `short_enum`"] # [doc = " so the only valid spec for LLVM is c_int::BITS or 8"] pub c_enum_min_size : Integer , }}}
mkitem!{mkimpl!{impl Default for TargetDataLayout { # [doc = " Creates an instance of `TargetDataLayout`."] fn default () -> TargetDataLayout { let align = | bits | Align :: from_bits (bits) . unwrap () ; TargetDataLayout { endian : Endian :: Big , i1_align : AbiAlign :: new (align (8)) , i8_align : AbiAlign :: new (align (8)) , i16_align : AbiAlign :: new (align (16)) , i32_align : AbiAlign :: new (align (32)) , i64_align : AbiAlign :: new (align (32)) , i128_align : AbiAlign :: new (align (32)) , f16_align : AbiAlign :: new (align (16)) , f32_align : AbiAlign :: new (align (32)) , f64_align : AbiAlign :: new (align (64)) , f128_align : AbiAlign :: new (align (128)) , aggregate_align : AbiAlign { abi : align (8) } , vector_align : vec ! [(Size :: from_bits (64) , AbiAlign :: new (align (64))) , (Size :: from_bits (128) , AbiAlign :: new (align (128))) ,] , default_address_space : AddressSpace :: ZERO , default_address_space_pointer_spec : PointerSpec { pointer_size : Size :: from_bits (64) , pointer_align : AbiAlign :: new (align (64)) , pointer_offset : Size :: from_bits (64) , _is_fat : false , } , address_space_info : vec ! [] , instruction_address_space : AddressSpace :: ZERO , c_enum_min_size : Integer :: I32 , } } }}}
mkitem!{mkenum!{pub enum TargetDataLayoutErrors < 'a > { InvalidAddressSpace { addr_space : & 'a str , cause : & 'a str , err : ParseIntError } , InvalidBits { kind : & 'a str , bit : & 'a str , cause : & 'a str , err : ParseIntError } , MissingAlignment { cause : & 'a str } , InvalidAlignment { cause : & 'a str , err : AlignFromBytesError } , InconsistentTargetArchitecture { dl : & 'a str , target : & 'a str } , InconsistentTargetPointerWidth { pointer_size : u64 , target : u16 } , InvalidBitsSize { err : String } , UnknownPointerSpecification { err : String } , }}}
mkitem!{mkimpl!{impl TargetDataLayout { # [doc = " Parse data layout from an"] # [doc = " [llvm data layout string](https://llvm.org/docs/LangRef.html#data-layout)"] # [doc = ""] # [doc = " This function doesn't fill `c_enum_min_size` and it will always be `I32` since it can not be"] # [doc = " determined from llvm string."] pub fn parse_from_llvm_datalayout_string < 'a > (input : & 'a str , default_address_space : AddressSpace ,) -> Result < TargetDataLayout , TargetDataLayoutErrors < 'a > > { let parse_address_space = | s : & 'a str , cause : & 'a str | { s . parse :: < u32 > () . map (AddressSpace) . map_err (| err | { TargetDataLayoutErrors :: InvalidAddressSpace { addr_space : s , cause , err } }) } ; let parse_bits = | s : & 'a str , kind : & 'a str , cause : & 'a str | { s . parse :: < u64 > () . map_err (| err | TargetDataLayoutErrors :: InvalidBits { kind , bit : s , cause , err , }) } ; let parse_size = | s : & 'a str , cause : & 'a str | parse_bits (s , "size" , cause) . map (Size :: from_bits) ; let parse_align_str = | s : & 'a str , cause : & 'a str | { let align_from_bits = | bits | { Align :: from_bits (bits) . map_err (| err | TargetDataLayoutErrors :: InvalidAlignment { cause , err }) } ; let abi = parse_bits (s , "alignment" , cause) ? ; Ok (AbiAlign :: new (align_from_bits (abi) ?)) } ; let parse_align_seq = | s : & [& 'a str] , cause : & 'a str | { if s . is_empty () { return Err (TargetDataLayoutErrors :: MissingAlignment { cause }) ; } parse_align_str (s [0] , cause) } ; let mut dl = TargetDataLayout :: default () ; dl . default_address_space = default_address_space ; let mut i128_align_src = 64 ; for spec in input . split ('-') { let spec_parts = spec . split (':') . collect :: < Vec < _ > > () ; match & * spec_parts { ["e"] => dl . endian = Endian :: Little , ["E"] => dl . endian = Endian :: Big , [p] if p . starts_with ('P') => { dl . instruction_address_space = parse_address_space (& p [1 ..] , "P") ? } ["a" , a @ ..] => dl . aggregate_align = parse_align_seq (a , "a") ? , ["f16" , a @ ..] => dl . f16_align = parse_align_seq (a , "f16") ? , ["f32" , a @ ..] => dl . f32_align = parse_align_seq (a , "f32") ? , ["f64" , a @ ..] => dl . f64_align = parse_align_seq (a , "f64") ? , ["f128" , a @ ..] => dl . f128_align = parse_align_seq (a , "f128") ? , [p , s , a @ ..] if p . starts_with ("p") => { let mut p = p . strip_prefix ('p') . unwrap () ; let mut _is_fat = false ; if p . starts_with ('f') { p = p . strip_prefix ('f') . unwrap () ; _is_fat = true ; } if p . starts_with (char :: is_alphabetic) { return Err (TargetDataLayoutErrors :: UnknownPointerSpecification { err : p . to_string () , }) ; } let addr_space = if ! p . is_empty () { parse_address_space (p , "p-") ? } else { AddressSpace :: ZERO } ; let pointer_size = parse_size (s , "p-") ? ; let pointer_align = parse_align_seq (a , "p-") ? ; let info = PointerSpec { pointer_offset : pointer_size , pointer_size , pointer_align , _is_fat , } ; if addr_space == default_address_space { dl . default_address_space_pointer_spec = info ; } else { match dl . address_space_info . iter_mut () . find (| (a , _) | * a == addr_space) { Some (e) => e . 1 = info , None => { dl . address_space_info . push ((addr_space , info)) ; } } } } [p , s , a , _pr , i] if p . starts_with ("p") => { let mut p = p . strip_prefix ('p') . unwrap () ; let mut _is_fat = false ; if p . starts_with ('f') { p = p . strip_prefix ('f') . unwrap () ; _is_fat = true ; } if p . starts_with (char :: is_alphabetic) { return Err (TargetDataLayoutErrors :: UnknownPointerSpecification { err : p . to_string () , }) ; } let addr_space = if ! p . is_empty () { parse_address_space (p , "p") ? } else { AddressSpace :: ZERO } ; let info = PointerSpec { pointer_size : parse_size (s , "p-") ? , pointer_align : parse_align_str (a , "p-") ? , pointer_offset : parse_size (i , "p-") ? , _is_fat , } ; if addr_space == default_address_space { dl . default_address_space_pointer_spec = info ; } else { match dl . address_space_info . iter_mut () . find (| (a , _) | * a == addr_space) { Some (e) => e . 1 = info , None => { dl . address_space_info . push ((addr_space , info)) ; } } } } [s , a @ ..] if s . starts_with ('i') => { let Ok (bits) = s [1 ..] . parse :: < u64 > () else { parse_size (& s [1 ..] , "i") ? ; continue ; } ; let a = parse_align_seq (a , s) ? ; match bits { 1 => dl . i1_align = a , 8 => dl . i8_align = a , 16 => dl . i16_align = a , 32 => dl . i32_align = a , 64 => dl . i64_align = a , _ => { } } if bits >= i128_align_src && bits <= 128 { i128_align_src = bits ; dl . i128_align = a ; } } [s , a @ ..] if s . starts_with ('v') => { let v_size = parse_size (& s [1 ..] , "v") ? ; let a = parse_align_seq (a , s) ? ; if let Some (v) = dl . vector_align . iter_mut () . find (| v | v . 0 == v_size) { v . 1 = a ; continue ; } dl . vector_align . push ((v_size , a)) ; } _ => { } } } if (dl . instruction_address_space != dl . default_address_space) && dl . address_space_info . iter () . find (| (a , _) | * a == dl . instruction_address_space) . is_none () { dl . address_space_info . push ((dl . instruction_address_space , dl . default_address_space_pointer_spec . clone () ,)) ; } Ok (dl) } # [doc = " Returns **exclusive** upper bound on object size in bytes, in the default data address"] # [doc = " space."] # [doc = ""] # [doc = " The theoretical maximum object size is defined as the maximum positive `isize` value."] # [doc = " This ensures that the `offset` semantics remain well-defined by allowing it to correctly"] # [doc = " index every address within an object along with one byte past the end, along with allowing"] # [doc = " `isize` to store the difference between any two pointers into an object."] # [doc = ""] # [doc = " LLVM uses a 64-bit integer to represent object size in *bits*, but we care only for bytes,"] # [doc = " so we adopt such a more-constrained size bound due to its technical limitations."] # [inline] pub fn obj_size_bound (& self) -> u64 { match self . pointer_size () . bits () { 16 => 1 << 15 , 32 => 1 << 31 , 64 => 1 << 61 , bits => panic ! ("obj_size_bound: unknown pointer bit size {bits}") , } } # [doc = " Returns **exclusive** upper bound on object size in bytes."] # [doc = ""] # [doc = " The theoretical maximum object size is defined as the maximum positive `isize` value."] # [doc = " This ensures that the `offset` semantics remain well-defined by allowing it to correctly"] # [doc = " index every address within an object along with one byte past the end, along with allowing"] # [doc = " `isize` to store the difference between any two pointers into an object."] # [doc = ""] # [doc = " LLVM uses a 64-bit integer to represent object size in *bits*, but we care only for bytes,"] # [doc = " so we adopt such a more-constrained size bound due to its technical limitations."] # [inline] pub fn obj_size_bound_in (& self , address_space : AddressSpace) -> u64 { match self . pointer_size_in (address_space) . bits () { 16 => 1 << 15 , 32 => 1 << 31 , 64 => 1 << 61 , bits => panic ! ("obj_size_bound: unknown pointer bit size {bits}") , } } # [inline] pub fn ptr_sized_integer (& self) -> Integer { use Integer :: * ; match self . pointer_offset () . bits () { 16 => I16 , 32 => I32 , 64 => I64 , bits => panic ! ("ptr_sized_integer: unknown pointer bit size {bits}") , } } # [inline] pub fn ptr_sized_integer_in (& self , address_space : AddressSpace) -> Integer { use Integer :: * ; match self . pointer_offset_in (address_space) . bits () { 16 => I16 , 32 => I32 , 64 => I64 , bits => panic ! ("ptr_sized_integer: unknown pointer bit size {bits}") , } } # [doc = " psABI-mandated alignment for a vector type, if any"] # [inline] fn cabi_vector_align (& self , vec_size : Size) -> Option < AbiAlign > { self . vector_align . iter () . find (| (size , _align) | * size == vec_size) . map (| (_size , align) | * align) } # [doc = " an alignment resembling the one LLVM would pick for a vector"] # [inline] pub fn llvmlike_vector_align (& self , vec_size : Size) -> AbiAlign { self . cabi_vector_align (vec_size) . unwrap_or (AbiAlign :: new (Align :: from_bytes (vec_size . bytes () . next_power_of_two ()) . unwrap () ,)) } # [doc = " Get the pointer size in the default data address space."] # [inline] pub fn pointer_size (& self) -> Size { self . default_address_space_pointer_spec . pointer_size } # [doc = " Get the pointer size in a specific address space."] # [inline] pub fn pointer_size_in (& self , c : AddressSpace) -> Size { if c == self . default_address_space { return self . default_address_space_pointer_spec . pointer_size ; } if let Some (e) = self . address_space_info . iter () . find (| (a , _) | a == & c) { e . 1 . pointer_size } else { panic ! ("Use of unknown address space {c:?}") ; } } # [doc = " Get the pointer index in the default data address space."] # [inline] pub fn pointer_offset (& self) -> Size { self . default_address_space_pointer_spec . pointer_offset } # [doc = " Get the pointer index in a specific address space."] # [inline] pub fn pointer_offset_in (& self , c : AddressSpace) -> Size { if c == self . default_address_space { return self . default_address_space_pointer_spec . pointer_offset ; } if let Some (e) = self . address_space_info . iter () . find (| (a , _) | a == & c) { e . 1 . pointer_offset } else { panic ! ("Use of unknown address space {c:?}") ; } } # [doc = " Get the pointer alignment in the default data address space."] # [inline] pub fn pointer_align (& self) -> AbiAlign { self . default_address_space_pointer_spec . pointer_align } # [doc = " Get the pointer alignment in a specific address space."] # [inline] pub fn pointer_align_in (& self , c : AddressSpace) -> AbiAlign { if c == self . default_address_space { return self . default_address_space_pointer_spec . pointer_align ; } if let Some (e) = self . address_space_info . iter () . find (| (a , _) | a == & c) { e . 1 . pointer_align } else { panic ! ("Use of unknown address space {c:?}") ; } } }}}
