mkitem!{mkstruct!{# [doc = " Size of a type in bytes."] # [derive (Copy , Clone , PartialEq , Eq , PartialOrd , Ord , Hash)] # [cfg_attr (feature = "nightly" , derive (Encodable_NoContext , Decodable_NoContext , HashStable_Generic))] pub struct Size { raw : u64 , }}}
