mkitem!{mkimpl!{impl Size { pub const ZERO : Size = Size { raw : 0 } ; # [doc = " Rounds `bits` up to the next-higher byte boundary, if `bits` is"] # [doc = " not a multiple of 8."] pub fn from_bits (bits : impl TryInto < u64 >) -> Size { let bits = bits . try_into () . ok () . unwrap () ; Size { raw : bits . div_ceil (8) } } # [inline] pub fn from_bytes (bytes : impl TryInto < u64 >) -> Size { let bytes : u64 = bytes . try_into () . ok () . unwrap () ; Size { raw : bytes } } # [inline] pub fn bytes (self) -> u64 { self . raw } # [inline] pub fn bytes_usize (self) -> usize { self . bytes () . try_into () . unwrap () } # [inline] pub fn bits (self) -> u64 { # [cold] fn overflow (bytes : u64) -> ! { panic ! ("Size::bits: {bytes} bytes in bits doesn't fit in u64") } self . bytes () . checked_mul (8) . unwrap_or_else (| | overflow (self . bytes ())) } # [inline] pub fn bits_usize (self) -> usize { self . bits () . try_into () . unwrap () } # [inline] pub fn align_to (self , align : Align) -> Size { let mask = align . bytes () - 1 ; Size :: from_bytes ((self . bytes () + mask) & ! mask) } # [inline] pub fn is_aligned (self , align : Align) -> bool { let mask = align . bytes () - 1 ; self . bytes () & mask == 0 } # [inline] pub fn checked_add < C : HasDataLayout > (self , offset : Size , cx : & C) -> Option < Size > { let dl = cx . data_layout () ; let bytes = self . bytes () . checked_add (offset . bytes ()) ? ; if bytes < dl . obj_size_bound () { Some (Size :: from_bytes (bytes)) } else { None } } # [inline] pub fn checked_mul < C : HasDataLayout > (self , count : u64 , cx : & C) -> Option < Size > { let dl = cx . data_layout () ; let bytes = self . bytes () . checked_mul (count) ? ; if bytes < dl . obj_size_bound () { Some (Size :: from_bytes (bytes)) } else { None } } # [doc = " Truncates `value` to `self` bits and then sign-extends it to 128 bits"] # [doc = " (i.e., if it is negative, fill with 1's on the left)."] # [inline] pub fn sign_extend (self , value : u128) -> i128 { let size = self . bits () ; if size == 0 { return 0 ; } let shift = 128 - size ; ((value << shift) as i128) >> shift } # [doc = " Truncates `value` to `self` bits."] # [inline] pub fn truncate (self , value : u128) -> u128 { let size = self . bits () ; if size == 0 { return 0 ; } let shift = 128 - size ; (value << shift) >> shift } # [inline] pub fn signed_int_min (& self) -> i128 { self . sign_extend (1_u128 << (self . bits () - 1)) } # [inline] pub fn signed_int_max (& self) -> i128 { i128 :: MAX >> (128 - self . bits ()) } # [inline] pub fn unsigned_int_max (& self) -> u128 { u128 :: MAX >> (128 - self . bits ()) } }}}
