mkitem!{mkstruct!{# [doc = " Inclusive wrap-around range of valid values, that is, if"] # [doc = " start > end, it represents `start..=MAX`, followed by `0..=end`."] # [doc = ""] # [doc = " That is, for an i8 primitive, a range of `254..=2` means following"] # [doc = " sequence:"] # [doc = ""] # [doc = "    254 (-2), 255 (-1), 0, 1, 2"] # [doc = ""] # [doc = " This is intended specifically to mirror LLVM’s `!range` metadata semantics."] # [derive (Clone , Copy , PartialEq , Eq , Hash)] # [cfg_attr (feature = "nightly" , derive (HashStable_Generic))] pub struct WrappingRange { pub start : u128 , pub end : u128 , }}}
mkitem!{mkimpl!{impl WrappingRange { pub fn full (size : Size) -> Self { Self { start : 0 , end : size . unsigned_int_max () } } # [doc = " Returns `true` if `v` is contained in the range."] # [inline (always)] pub fn contains (& self , v : u128) -> bool { if self . start <= self . end { self . start <= v && v <= self . end } else { self . start <= v || v <= self . end } } # [doc = " Returns `true` if all the values in `other` are contained in this range,"] # [doc = " when the values are considered as having width `size`."] # [inline (always)] pub fn contains_range (& self , other : Self , size : Size) -> bool { if self . is_full_for (size) { true } else { let trunc = | x | size . truncate (x) ; let delta = self . start ; let max = trunc (self . end . wrapping_sub (delta)) ; let other_start = trunc (other . start . wrapping_sub (delta)) ; let other_end = trunc (other . end . wrapping_sub (delta)) ; (other_start <= other_end) && (other_end <= max) } } # [doc = " Returns `self` with replaced `start`"] # [inline (always)] fn with_start (mut self , start : u128) -> Self { self . start = start ; self } # [doc = " Returns `self` with replaced `end`"] # [inline (always)] fn with_end (mut self , end : u128) -> Self { self . end = end ; self } # [doc = " Returns `true` if `size` completely fills the range."] # [doc = ""] # [doc = " Note that this is *not* the same as `self == WrappingRange::full(size)`."] # [doc = " Niche calculations can produce full ranges which are not the canonical one;"] # [doc = " for example `Option<NonZero<u16>>` gets `valid_range: (..=0) | (1..)`."] # [inline] fn is_full_for (& self , size : Size) -> bool { let max_value = size . unsigned_int_max () ; debug_assert ! (self . start <= max_value && self . end <= max_value) ; self . start == (self . end . wrapping_add (1) & max_value) } # [doc = " Checks whether this range is considered non-wrapping when the values are"] # [doc = " interpreted as *unsigned* numbers of width `size`."] # [doc = ""] # [doc = " Returns `Ok(true)` if there's no wrap-around, `Ok(false)` if there is,"] # [doc = " and `Err(..)` if the range is full so it depends how you think about it."] # [inline] pub fn no_unsigned_wraparound (& self , size : Size) -> Result < bool , RangeFull > { if self . is_full_for (size) { Err (..) } else { Ok (self . start <= self . end) } } # [doc = " Checks whether this range is considered non-wrapping when the values are"] # [doc = " interpreted as *signed* numbers of width `size`."] # [doc = ""] # [doc = " This is heavily dependent on the `size`, as `100..=200` does wrap when"] # [doc = " interpreted as `i8`, but doesn't when interpreted as `i16`."] # [doc = ""] # [doc = " Returns `Ok(true)` if there's no wrap-around, `Ok(false)` if there is,"] # [doc = " and `Err(..)` if the range is full so it depends how you think about it."] # [inline] pub fn no_signed_wraparound (& self , size : Size) -> Result < bool , RangeFull > { if self . is_full_for (size) { Err (..) } else { let start : i128 = size . sign_extend (self . start) ; let end : i128 = size . sign_extend (self . end) ; Ok (start <= end) } } }}}
mkitem!{mkimpl!{impl fmt :: Debug for WrappingRange { fn fmt (& self , fmt : & mut fmt :: Formatter < '_ >) -> fmt :: Result { if self . start > self . end { write ! (fmt , "(..={}) | ({}..)" , self . end , self . start) ? ; } else { write ! (fmt , "{}..={}" , self . start , self . end) ? ; } Ok (()) } }}}
