mkitem!{mkimpl!{impl Scalar { # [inline] pub fn is_bool (& self) -> bool { use Integer :: * ; matches ! (self , Scalar :: Initialized { value : Primitive :: Int (I8 , false) , valid_range : WrappingRange { start : 0 , end : 1 } }) } # [doc = " Get the primitive representation of this type, ignoring the valid range and whether the"] # [doc = " value is allowed to be undefined (due to being a union)."] pub fn primitive (& self) -> Primitive { match * self { Scalar :: Initialized { value , .. } | Scalar :: Union { value } => value , } } pub fn align (self , cx : & impl HasDataLayout) -> AbiAlign { self . primitive () . align (cx) } pub fn size (self , cx : & impl HasDataLayout) -> Size { self . primitive () . size (cx) } # [inline] pub fn to_union (& self) -> Self { Self :: Union { value : self . primitive () } } # [inline] pub fn valid_range (& self , cx : & impl HasDataLayout) -> WrappingRange { match * self { Scalar :: Initialized { valid_range , .. } => valid_range , Scalar :: Union { value } => WrappingRange :: full (value . size (cx)) , } } # [inline] # [doc = " Allows the caller to mutate the valid range. This operation will panic if attempted on a"] # [doc = " union."] pub fn valid_range_mut (& mut self) -> & mut WrappingRange { match self { Scalar :: Initialized { valid_range , .. } => valid_range , Scalar :: Union { .. } => panic ! ("cannot change the valid range of a union") , } } # [doc = " Returns `true` if all possible numbers are valid, i.e `valid_range` covers the whole"] # [doc = " layout."] # [inline] pub fn is_always_valid < C : HasDataLayout > (& self , cx : & C) -> bool { match * self { Scalar :: Initialized { valid_range , .. } => valid_range . is_full_for (self . size (cx)) , Scalar :: Union { .. } => true , } } # [doc = " Returns `true` if this type can be left uninit."] # [inline] pub fn is_uninit_valid (& self) -> bool { match * self { Scalar :: Initialized { .. } => false , Scalar :: Union { .. } => true , } } # [doc = " Returns `true` if this is a signed integer scalar"] # [inline] pub fn is_signed (& self) -> bool { match self . primitive () { Primitive :: Int (_ , signed) => signed , _ => false , } } }}}
mkitem!{mkenum!{# [doc = " Describes how the fields of a type are located in memory."] # [derive (PartialEq , Eq , Hash , Clone , Debug)] # [cfg_attr (feature = "nightly" , derive (HashStable_Generic))] pub enum FieldsShape < FieldIdx : Idx > { # [doc = " Scalar primitives and `!`, which never have fields."] Primitive , # [doc = " All fields start at no offset. The `usize` is the field count."] Union (NonZeroUsize) , # [doc = " Array/vector-like placement, with all fields of identical types."] Array { stride : Size , count : u64 } , # [doc = " Struct-like placement, with precomputed offsets."] # [doc = ""] # [doc = " Fields are guaranteed to not overlap, but note that gaps"] # [doc = " before, between and after all the fields are NOT always"] # [doc = " padding, and as such their contents may not be discarded."] # [doc = " For example, enum variants leave a gap at the start,"] # [doc = " where the discriminant field in the enum layout goes."] Arbitrary { # [doc = " Offsets for the first byte of each field,"] # [doc = " ordered to match the source definition order."] # [doc = " This vector does not go in increasing order."] offsets : IndexVec < FieldIdx , Size > , # [doc = " Maps source order field indices to memory order indices,"] # [doc = " depending on how the fields were reordered (if at all)."] # [doc = " This is a permutation, with both the source order and the"] # [doc = " memory order using the same (0..n) index ranges."] # [doc = ""] # [doc = " Note that during computation of `memory_index`, sometimes"] # [doc = " it is easier to operate on the inverse mapping (that is,"] # [doc = " from memory order to source order), and that is usually"] # [doc = " named `inverse_memory_index`."] # [doc = ""] memory_index : IndexVec < FieldIdx , u32 > , } , }}}
mkitem!{mkimpl!{impl < FieldIdx : Idx > FieldsShape < FieldIdx > { # [inline] pub fn count (& self) -> usize { match * self { FieldsShape :: Primitive => 0 , FieldsShape :: Union (count) => count . get () , FieldsShape :: Array { count , .. } => count . try_into () . unwrap () , FieldsShape :: Arbitrary { ref offsets , .. } => offsets . len () , } } # [inline] pub fn offset (& self , i : usize) -> Size { match * self { FieldsShape :: Primitive => { unreachable ! ("FieldsShape::offset: `Primitive`s have no fields") } FieldsShape :: Union (count) => { assert ! (i < count . get () , "tried to access field {i} of union with {count} fields") ; Size :: ZERO } FieldsShape :: Array { stride , count } => { let i = u64 :: try_from (i) . unwrap () ; assert ! (i < count , "tried to access field {i} of array with {count} fields") ; stride * i } FieldsShape :: Arbitrary { ref offsets , .. } => offsets [FieldIdx :: new (i)] , } } # [inline] pub fn memory_index (& self , i : usize) -> usize { match * self { FieldsShape :: Primitive => { unreachable ! ("FieldsShape::memory_index: `Primitive`s have no fields") } FieldsShape :: Union (_) | FieldsShape :: Array { .. } => i , FieldsShape :: Arbitrary { ref memory_index , .. } => { memory_index [FieldIdx :: new (i)] . try_into () . unwrap () } } } # [doc = " Gets source indices of the fields by increasing offsets."] # [inline] pub fn index_by_increasing_offset (& self) -> impl ExactSizeIterator < Item = usize > { let mut inverse_small = [0u8 ; 64] ; let mut inverse_big = IndexVec :: new () ; let use_small = self . count () <= inverse_small . len () ; if let FieldsShape :: Arbitrary { ref memory_index , .. } = * self { if use_small { for (field_idx , & mem_idx) in memory_index . iter_enumerated () { inverse_small [mem_idx as usize] = field_idx . index () as u8 ; } } else { inverse_big = memory_index . invert_bijective_mapping () ; } } let pseudofield_count = if let FieldsShape :: Primitive = self { 1 } else { self . count () } ; (0 .. pseudofield_count) . map (move | i | match * self { FieldsShape :: Primitive | FieldsShape :: Union (_) | FieldsShape :: Array { .. } => i , FieldsShape :: Arbitrary { .. } => { if use_small { inverse_small [i] as usize } else { inverse_big [i as u32] . index () } } }) } }}}
mkitem!{mkstruct!{# [doc = " An identifier that specifies the address space that some operation"] # [doc = " should operate on. Special address spaces have an effect on code generation,"] # [doc = " depending on the target and the address spaces it implements."] # [derive (Copy , Clone , Debug , PartialEq , Eq , PartialOrd , Ord , Hash)] # [cfg_attr (feature = "nightly" , derive (HashStable_Generic))] pub struct AddressSpace (pub u32) ;}}
