mkitem!{mkenum!{# [doc = " The way we represent values to the backend"] # [doc = ""] # [doc = " Previously this was conflated with the \"ABI\" a type is given, as in the platform-specific ABI."] # [doc = " In reality, this implies little about that, but is mostly used to describe the syntactic form"] # [doc = " emitted for the backend, as most backends handle SSA values and blobs of memory differently."] # [doc = " The psABI may need consideration in doing so, but this enum does not constitute a promise for"] # [doc = " how the value will be lowered to the calling convention, in itself."] # [doc = ""] # [doc = " Generally, a codegen backend will prefer to handle smaller values as a scalar or short vector,"] # [doc = " and larger values will usually prefer to be represented as memory."] # [derive (Clone , Copy , PartialEq , Eq , Hash , Debug)] # [cfg_attr (feature = "nightly" , derive (HashStable_Generic))] pub enum BackendRepr { Scalar (Scalar) , ScalarPair (Scalar , Scalar) , SimdVector { element : Scalar , count : u64 , } , Memory { # [doc = " If true, the size is exact, otherwise it's only a lower bound."] sized : bool , } , }}}
mkitem!{mkimpl!{impl BackendRepr { # [doc = " Returns `true` if the layout corresponds to an unsized type."] # [inline] pub fn is_unsized (& self) -> bool { match * self { BackendRepr :: Scalar (_) | BackendRepr :: ScalarPair (..) | BackendRepr :: SimdVector { .. } => false , BackendRepr :: Memory { sized } => ! sized , } } # [inline] pub fn is_sized (& self) -> bool { ! self . is_unsized () } # [doc = " Returns `true` if this is a single signed integer scalar."] # [doc = " Sanity check: panics if this is not a scalar type (see PR #70189)."] # [inline] pub fn is_signed (& self) -> bool { match self { BackendRepr :: Scalar (scal) => scal . is_signed () , _ => panic ! ("`is_signed` on non-scalar ABI {self:?}") , } } # [doc = " Returns `true` if this is a scalar type"] # [inline] pub fn is_scalar (& self) -> bool { matches ! (* self , BackendRepr :: Scalar (_)) } # [doc = " Returns `true` if this is a bool"] # [inline] pub fn is_bool (& self) -> bool { matches ! (* self , BackendRepr :: Scalar (s) if s . is_bool ()) } # [doc = " The psABI alignment for a `Scalar` or `ScalarPair`"] # [doc = ""] # [doc = " `None` for other variants."] pub fn scalar_align < C : HasDataLayout > (& self , cx : & C) -> Option < Align > { match * self { BackendRepr :: Scalar (s) => Some (s . align (cx) . abi) , BackendRepr :: ScalarPair (s1 , s2) => Some (s1 . align (cx) . max (s2 . align (cx)) . abi) , BackendRepr :: SimdVector { .. } | BackendRepr :: Memory { .. } => None , } } # [doc = " The psABI size for a `Scalar` or `ScalarPair`"] # [doc = ""] # [doc = " `None` for other variants"] pub fn scalar_size < C : HasDataLayout > (& self , cx : & C) -> Option < Size > { match * self { BackendRepr :: Scalar (s) => Some (s . size (cx)) , BackendRepr :: ScalarPair (s1 , s2) => { let field2_offset = s1 . size (cx) . align_to (s2 . align (cx) . abi) ; let size = (field2_offset + s2 . size (cx)) . align_to (self . scalar_align (cx) . unwrap () ,) ; Some (size) } BackendRepr :: SimdVector { .. } | BackendRepr :: Memory { .. } => None , } } # [doc = " Discard validity range information and allow undef."] pub fn to_union (& self) -> Self { match * self { BackendRepr :: Scalar (s) => BackendRepr :: Scalar (s . to_union ()) , BackendRepr :: ScalarPair (s1 , s2) => { BackendRepr :: ScalarPair (s1 . to_union () , s2 . to_union ()) } BackendRepr :: SimdVector { element , count } => { BackendRepr :: SimdVector { element : element . to_union () , count } } BackendRepr :: Memory { .. } => BackendRepr :: Memory { sized : true } , } } pub fn eq_up_to_validity (& self , other : & Self) -> bool { match (self , other) { (BackendRepr :: Scalar (l) , BackendRepr :: Scalar (r)) => l . primitive () == r . primitive () , (BackendRepr :: SimdVector { element : element_l , count : count_l } , BackendRepr :: SimdVector { element : element_r , count : count_r } ,) => element_l . primitive () == element_r . primitive () && count_l == count_r , (BackendRepr :: ScalarPair (l1 , l2) , BackendRepr :: ScalarPair (r1 , r2)) => { l1 . primitive () == r1 . primitive () && l2 . primitive () == r2 . primitive () } _ => self == other , } } }}}
