mkitem!{mkstruct!{# [doc = " After we borrow check a closure, we are left with various"] # [doc = " requirements that we have inferred between the free regions that"] # [doc = " appear in the closure's signature or on its field types. These"] # [doc = " requirements are then verified and proved by the closure's"] # [doc = " creating function. This struct encodes those requirements."] # [doc = ""] # [doc = " The requirements are listed as being between various `RegionVid`. The 0th"] # [doc = " region refers to `'static`; subsequent region vids refer to the free"] # [doc = " regions that appear in the closure (or coroutine's) type, in order of"] # [doc = " appearance. (This numbering is actually defined by the `UniversalRegions`"] # [doc = " struct in the NLL region checker. See for example"] # [doc = " `UniversalRegions::closure_mapping`.) Note the free regions in the"] # [doc = " closure's signature and captures are erased."] # [doc = ""] # [doc = " Example: If type check produces a closure with the closure args:"] # [doc = ""] # [doc = " ```text"] # [doc = " ClosureArgs = ["] # [doc = "     'a,                                         // From the parent."] # [doc = "     'b,"] # [doc = "     i8,                                         // the \"closure kind\""] # [doc = "     for<'x> fn(&'<erased> &'x u32) -> &'x u32,  // the \"closure signature\""] # [doc = "     &'<erased> String,                          // some upvar"] # [doc = " ]"] # [doc = " ```"] # [doc = ""] # [doc = " We would \"renumber\" each free region to a unique vid, as follows:"] # [doc = ""] # [doc = " ```text"] # [doc = " ClosureArgs = ["] # [doc = "     '1,                                         // From the parent."] # [doc = "     '2,"] # [doc = "     i8,                                         // the \"closure kind\""] # [doc = "     for<'x> fn(&'3 &'x u32) -> &'x u32,         // the \"closure signature\""] # [doc = "     &'4 String,                                 // some upvar"] # [doc = " ]"] # [doc = " ```"] # [doc = ""] # [doc = " Now the code might impose a requirement like `'1: '2`. When an"] # [doc = " instance of the closure is created, the corresponding free regions"] # [doc = " can be extracted from its type and constrained to have the given"] # [doc = " outlives relationship."] # [derive (Clone , Debug)] pub struct ClosureRegionRequirements < 'tcx > { # [doc = " The number of external regions defined on the closure. In our"] # [doc = " example above, it would be 3 -- one for `'static`, then `'1`"] # [doc = " and `'2`. This is just used for a sanity check later on, to"] # [doc = " make sure that the number of regions we see at the callsite"] # [doc = " matches."] pub num_external_vids : usize , # [doc = " Requirements between the various free regions defined in"] # [doc = " indices."] pub outlives_requirements : Vec < ClosureOutlivesRequirement < 'tcx > > , }}}
mkitem!{mkstruct!{# [doc = " Indicates an outlives-constraint between a type or between two"] # [doc = " free regions declared on the closure."] # [derive (Copy , Clone , Debug)] pub struct ClosureOutlivesRequirement < 'tcx > { pub subject : ClosureOutlivesSubject < 'tcx > , pub outlived_free_region : ty :: RegionVid , pub blame_span : Span , pub category : ConstraintCategory < 'tcx > , }}}
