mkitem!{mkstruct!{# [doc = " Represents a span."] # [doc = ""] # [doc = " Spans represent a region of code, used for error reporting. Positions in spans"] # [doc = " are *absolute* positions from the beginning of the [`SourceMap`], not positions"] # [doc = " relative to [`SourceFile`]s. Methods on the `SourceMap` can be used to relate spans back"] # [doc = " to the original source."] # [doc = ""] # [doc = " You must be careful if the span crosses more than one file, since you will not be"] # [doc = " able to use many of the functions on spans in source_map and you cannot assume"] # [doc = " that the length of the span is equal to `span.hi - span.lo`; there may be space in the"] # [doc = " [`BytePos`] range between files."] # [doc = ""] # [doc = " `SpanData` is public because `Span` uses a thread-local interner and can't be"] # [doc = " sent to other threads, but some pieces of performance infra run in a separate thread."] # [doc = " Using `Span` is generally preferred."] # [derive (Clone , Copy , Hash , PartialEq , Eq)] # [derive_where (PartialOrd , Ord)] pub struct SpanData { pub lo : BytePos , pub hi : BytePos , # [doc = " Information about where the macro came from, if this piece of"] # [doc = " code was created by a macro expansion."] # [derive_where (skip)] pub ctxt : SyntaxContext , # [derive_where (skip)] pub parent : Option < LocalDefId > , }}}
mkitem!{mkimpl!{impl SpanData { # [inline] pub fn span (& self) -> Span { Span :: new (self . lo , self . hi , self . ctxt , self . parent) } # [inline] pub fn with_lo (& self , lo : BytePos) -> Span { Span :: new (lo , self . hi , self . ctxt , self . parent) } # [inline] pub fn with_hi (& self , hi : BytePos) -> Span { Span :: new (self . lo , hi , self . ctxt , self . parent) } # [doc = " Avoid if possible, `Span::map_ctxt` should be preferred."] # [inline] fn with_ctxt (& self , ctxt : SyntaxContext) -> Span { Span :: new (self . lo , self . hi , ctxt , self . parent) } # [doc = " Avoid if possible, `Span::with_parent` should be preferred."] # [inline] fn with_parent (& self , parent : Option < LocalDefId >) -> Span { Span :: new (self . lo , self . hi , self . ctxt , parent) } # [doc = " Returns `true` if this is a dummy span with any hygienic context."] # [inline] pub fn is_dummy (self) -> bool { self . lo . 0 == 0 && self . hi . 0 == 0 } # [doc = " Returns `true` if `self` fully encloses `other`."] pub fn contains (self , other : Self) -> bool { self . lo <= other . lo && other . hi <= self . hi } }}}
mkitem!{mkimpl!{impl Default for SpanData { fn default () -> Self { Self { lo : BytePos (0) , hi : BytePos (0) , ctxt : SyntaxContext :: root () , parent : None } } }}}
mkitem!{mkimpl!{impl PartialOrd for Span { fn partial_cmp (& self , rhs : & Self) -> Option < Ordering > { PartialOrd :: partial_cmp (& self . data () , & rhs . data ()) } }}}
